css:
.loader {
  position: relative;
  width: 50px;
  height: 44px;
}
.loader::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 0;
  width: 3px;
  height: 100%;
  border-radius: 2px;
  background: #4338ca;
}
.loader i {
  position: absolute;
  left: 7px;
  top: 6px;
  width: 38px;
  height: 24px;
  border-radius: 2px;
  background-color: #eef2ff;
  background-image: conic-gradient(#6366f1 25%, transparent 0 50%, #6366f1 0 75%, transparent 0);
  background-size: 10px 10px;
  transform-origin: left center;
  animation: flag 1.1s ease-in-out infinite;
}
@keyframes flag {
  0%, 100% { transform: skewY(0deg) skewX(0deg); }
  25% { transform: skewY(4deg) skewX(-4deg); }
  75% { transform: skewY(-4deg) skewX(4deg); }
}
